package mail

import (
	"context"
	"crypto/x509"
	"encoding/pem"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"lpa/internal/sysexec"
)

// A certificate for each mail domain.
//
// A mail domain whose site has a certificate covering mail.<domain> (AutoSSL
// asks for that name too) has it served for that name, by SNI, on SMTP,
// IMAP and POP3; any other name gets the hostname's certificate:
//
//	/etc/pki/lpanel-mail/sni/mail.<domain>/crt, key   a copy Exim's group can read
//	/etc/dovecot/lpanel/sni.conf                      Dovecot's local_name blocks for them
//
// Exim looks the name up in the folder on each connection (dsearch, so a
// name from a client never becomes part of a path by itself), so it needs no
// reload; Dovecot is reloaded when its list changes.

// sniDir holds the copies, one folder a name.
func (m *Manager) sniDir() string {
	return filepath.Join(m.TLSDir, "sni")
}

// mailName is the name a domain's mail is served under.
func mailName(domain string) string {
	return "mail." + domain
}

// applySNI copies each domain's certificate for mail.<domain>, when the
// certificate covers that name and is valid, and removes copies no domain of
// the account wants. It reports whether any copy changed.
func (m *Manager) applySNI(a ApplyArgs, had []string, eximGID int) (bool, error) {
	want := map[string]bool{}
	changed := false
	for _, d := range a.Domains {
		name := mailName(d.Name)
		if d.Cert == "" || m.Certs == nil || len(name) > maxDomain {
			continue
		}
		crt, key, err := m.Certs(a.Username, d.Cert)
		if err != nil {
			m.Log.Warn("a mail domain's certificate is not on the server", "domain", d.Name, "cert", d.Cert, "err", err)
			continue
		}
		chain, err := os.ReadFile(crt)
		if err != nil {
			return changed, err
		}
		if why := m.covers(chain, name); why != "" {
			m.Log.Info("the site's certificate does not serve mail", "name", name, "why", why)
			continue
		}
		keyPEM, err := os.ReadFile(key)
		if err != nil {
			return changed, err
		}
		dir := filepath.Join(m.sniDir(), name)
		if err := m.dir(m.TLSDir, 0o750, eximGID); err != nil {
			return changed, err
		}
		if err := m.dir(m.sniDir(), 0o750, eximGID); err != nil {
			return changed, err
		}
		if err := m.dir(dir, 0o750, eximGID); err != nil {
			return changed, err
		}
		// The key first: a new certificate is never paired with the old key.
		c1, err := m.writeFile(filepath.Join(dir, "key"), keyPEM, 0o640, eximGID)
		if err != nil {
			return changed, err
		}
		c2, err := m.writeFile(filepath.Join(dir, "crt"), chain, 0o640, eximGID)
		if err != nil {
			return changed, err
		}
		changed = changed || c1 || c2
		want[name] = true
	}
	for _, d := range append(append([]string{}, had...), names(a.Domains)...) {
		name := mailName(d)
		if dir := filepath.Join(m.sniDir(), name); !want[name] && exists(dir) {
			if err := os.RemoveAll(dir); err != nil {
				return changed, err
			}
			changed = true
		}
	}
	return changed, nil
}

// covers says why a certificate chain cannot serve name now ("" when it can).
func (m *Manager) covers(chain []byte, name string) string {
	block, _ := pem.Decode(chain)
	if block == nil || block.Type != "CERTIFICATE" {
		return "it is not a PEM certificate"
	}
	leaf, err := x509.ParseCertificate(block.Bytes)
	if err != nil {
		return err.Error()
	}
	if err := leaf.VerifyHostname(name); err != nil {
		return "it does not cover the name"
	}
	now := m.now()
	if now.Before(leaf.NotBefore) || now.After(leaf.NotAfter) {
		return "it is not valid now"
	}
	return ""
}

func names(domains []Domain) []string {
	out := make([]string, len(domains))
	for i, d := range domains {
		out[i] = d.Name
	}
	return out
}

// dovecotSNI writes Dovecot's local_name blocks for every copy on the server
// and reloads Dovecot when they changed, or when a copy did (Dovecot reads
// the files only when it loads its configuration).
func (m *Manager) dovecotSNI(ctx context.Context, dovecotGID int, copies bool) error {
	entries, err := os.ReadDir(m.sniDir())
	if err != nil && !errors.Is(err, fs.ErrNotExist) {
		return err
	}
	var list []string
	for _, e := range entries {
		dir := filepath.Join(m.sniDir(), e.Name())
		if e.IsDir() && checkDomain(e.Name()) == nil && exists(filepath.Join(dir, "crt")) && exists(filepath.Join(dir, "key")) {
			list = append(list, e.Name())
		}
	}
	sort.Strings(list)
	var b strings.Builder
	b.WriteString("# Generated by LPanel: each mail domain's own certificate, served for mail.<domain>.\n")
	for _, name := range list {
		dir := filepath.Join(m.sniDir(), name)
		fmt.Fprintf(&b, "local_name %s {\n  ssl_cert = <%s\n  ssl_key = <%s\n}\n", name, filepath.ToSlash(filepath.Join(dir, "crt")), filepath.ToSlash(filepath.Join(dir, "key")))
	}
	path := filepath.Join(m.DovecotDir, "sni.conf")
	old, _ := os.ReadFile(path)
	changed, err := m.writeFile(path, []byte(b.String()), 0o640, dovecotGID)
	// Nothing served before or now: nothing for Dovecot to load.
	if err != nil || (!changed && !copies) || (len(list) == 0 && !strings.Contains(string(old), "local_name")) {
		return err
	}
	if code, _, err := m.Run.Run(ctx, "systemctl", "is-active", "--quiet", "dovecot"); err != nil || code != 0 {
		return nil
	}
	return sysexec.Must(ctx, m.Run, "systemctl", "reload", "dovecot")
}
